90	/// Minimal, strict DER decoder and the slice of X.509 needed by `inspect`.
91	mod x509 {
92	    use std::fmt::Write;
93	
94	    pub(super) struct Cert {
95	        pub(super) subject: String,
96	        pub(super) issuer: String,
97	        pub(super) serial_hex: String,
98	        pub(super) not_before: String,
99	        pub(super) not_after: String,
100	    }
101	
102	    #[derive(Clone, Copy)]
103	    struct Tlv<'a> {
104	        tag: u8,
105	        content: &'a [u8],
106	    }
107	
108	    const TAG_INTEGER: u8 = 0x02;
109	    const TAG_BIT_STRING: u8 = 0x03;
110	    const TAG_OCTET_STRING: u8 = 0x04;
111	    const TAG_BOOLEAN: u8 = 0x01;
112	    const TAG_OID: u8 = 0x06;
113	    const TAG_SEQUENCE: u8 = 0x30;
114	    const TAG_SET: u8 = 0x31;
115	    const TAG_UTC_TIME: u8 = 0x17;
116	    const TAG_GENERALIZED_TIME: u8 = 0x18;
117	    const TAG_PRINTABLE_STRING: u8 = 0x13;
118	    const TAG_UNIVERSAL_STRING: u8 = 0x1C;
119	    const TAG_BMP_STRING: u8 = 0x1E;
120	
121	    /// Read exactly one DER TLV. Rejects indefinite length, non-minimal
122	    /// length encodings and truncated data.
123	    fn read_tlv(buf: &[u8]) -> Result<(Tlv<'_>, &[u8]), String> {
124	        let tag = *buf.first().ok_or_else(|| "unexpected end of data".to_string())?;
125	        if tag & 0x1F == 0x1F {
126	            return Err("multi-byte tags are not supported".to_string());
127	        }
128	        let first_len = *buf.get(1).ok_or_else(|| "truncated length".to_string())?;
129	        let (len, header_len) = match first_len {
130	            0x00..=0x7F => (first_len as usize, 2),
131	            0x80 => return Err("indefinite length is not valid DER".to_string()),
132	            0xFF => return Err("reserved length byte".to_string()),
133	            long => {
134	                let n = (long & 0x7F) as usize;
135	                if !(1..=4).contains(&n) {
136	                    return Err("length is too large".to_string());
137	                }
138	                let bytes = buf
139	                    .get(2..2 + n)
140	                    .ok_or_else(|| "truncated long length".to_string())?;
141	                if bytes[0] == 0 {
142	                    return Err("non-minimal length encoding".to_string());
143	                }
144	                let mut len = 0usize;
145	                for &b in bytes {
146	                    len = len
147	                        .checked_shl(8)
148	                        .and_then(|l| l.checked_add(b as usize))
149	                        .ok_or_else(|| "length overflow".to_string())?;
150	                }
151	                if len < 0x80 {
152	                    return Err("non-minimal length encoding".to_string());
153	                }
154	                (len, 2 + n)
155	            }
156	        };
157	        let total = header_len
158	            .checked_add(len)
159	            .filter(|&t| t <= buf.len())
160	            .ok_or_else(|| "truncated TLV content".to_string())?;
161	        Ok((
162	            Tlv {
163	                tag,
164	                content: &buf[header_len..total],
165	            },
166	            &buf[total..],
167	        ))
168	    }
169	
170	    fn read_tagged<'a>(
171	        buf: &'a [u8],
172	        tag: u8,
173	        what: &str,
174	    ) -> Result<(Tlv<'a>, &'a [u8]), String> {
175	        let (tlv, rest) = read_tlv(buf).map_err(|e| format!("{what}: {e}"))?;
176	        if tlv.tag != tag {
177	            return Err(format!("expected {what} (tag 0x{tag:02X}), got 0x{:02X}", tlv.tag));
178	        }
179	        Ok((tlv, rest))
180	    }
181	
182	    pub(super) fn parse(bytes: &[u8]) -> Result<Cert, String> {
183	        // Certificate ::= SEQUENCE { tbsCertificate, signatureAlgorithm,
184	        // signatureValue BIT STRING } — and nothing trailing.
185	        let (cert, rest) = read_tagged(bytes, TAG_SEQUENCE, "Certificate SEQUENCE")?;
186	        if !rest.is_empty() {
187	            return Err(format!("{} trailing byte(s) after certificate", rest.len()));
188	        }
189	
190	        let c = cert.content;
191	        let (tbs, c) = read_tagged(c, TAG_SEQUENCE, "tbsCertificate")?;
192	        let (outer_alg, c) = read_tagged(c, TAG_SEQUENCE, "outer signatureAlgorithm")?;
193	        let outer_alg = parse_signature_algorithm(outer_alg, "outer signatureAlgorithm")?;
194	        let (sig_value, c) = read_tlv(c)?;
195	        if sig_value.tag != TAG_BIT_STRING {
196	            return Err("signature must be a BIT STRING".to_string());
197	        }
198	        if sig_value.content.is_empty() || sig_value.content[0] > 7 {
199	            return Err("invalid signature BIT STRING".to_string());
200	        }
201	        if !c.is_empty() {
202	            return Err("trailing data in Certificate".to_string());
203	        }
204	
205	        // TBSCertificate ::= SEQUENCE {
206	        //   version [0] EXPLICIT Version DEFAULT v1, serialNumber, signature,
207	        //   issuer, validity, subject, subjectPublicKeyInfo, ... }
208	        let t = tbs.content;
209	        let (first, t2) = read_tlv(t)?;
210	        let (version, t) = if first.tag == 0xA0 {
211	            let (ver, vrest) = read_tagged(first.content, TAG_INTEGER, "version")?;
212	            if !vrest.is_empty() || ver.content.len() != 1 || ver.content[0] > 2 {
213	                return Err("invalid certificate version".to_string());
214	            }
215	            (ver.content[0], t2)
216	        } else {
217	            // No explicit version: v1 certificate.
218	            (0u8, t)
219	        };
220	
221	        let (serial, t3) = read_tagged(t, TAG_INTEGER, "serialNumber")?;
222	        let t = t3;
223	        let (tbs_alg, t) = read_tagged(t, TAG_SEQUENCE, "tbs signatureAlgorithm")?;
224	        let tbs_alg = parse_signature_algorithm(tbs_alg, "tbs signatureAlgorithm")?;
225	        if tbs_alg != outer_alg {
226	            return Err(mismatch_message(&outer_alg, &tbs_alg));
227	        }
228	        let (issuer, t) = read_tagged(t, TAG_SEQUENCE, "issuer")?;
229	        let (validity, t) = read_tagged(t, TAG_SEQUENCE, "validity")?;
230	        let (subject, t) = read_tagged(t, TAG_SEQUENCE, "subject")?;
231	        let (spki, t_after_spki) = read_tagged(t, TAG_SEQUENCE, "subjectPublicKeyInfo")?;
232	        check_spki(spki)?;
233	        // Optional tail of TBSCertificate, in a fixed order:
234	        //   issuerUniqueID  [1] IMPLICIT BIT STRING  (v2/v3, at most once)
235	        //   subjectUniqueID [2] IMPLICIT BIT STRING  (v2/v3, at most once)
236	        //   extensions      [3] EXPLICIT             (v3 only, at most once,
237	        //                                             and the last field)
238	        // Nothing else may follow subjectPublicKeyInfo: fields cannot be
239	        // skipped, reordered or dropped. The extensions interior is decoded in
240	        // full by `check_extensions`; the unique IDs carry BIT STRING content
241	        // directly (implicit tagging), validated by `check_bit_string`.
242	        let mut t = t_after_spki;
243	        let mut issuer_uid_seen = false;
244	        let mut subject_uid_seen = false;
245	        let mut extensions_present = false;
246	        while !t.is_empty() {
247	            let tag_hint = t.first().copied();
248	            let (field, rest) = read_tlv(t).map_err(|e| match tag_hint {
249	                Some(0x81) => format!("issuerUniqueID: {e}"),
250	                Some(0x82) => format!("subjectUniqueID: {e}"),
251	                // A truncated field whose tag is already readable can still
252	                // be located: tag 0xA3 is the extensions field.
253	                Some(0xA3) => format!("extensions field: {e}"),
254	                _ => e,
255	            })?;
256	            match field.tag {
257	                0x81 | 0x82 => {
258	                    let what = if field.tag == 0x81 {
259	                        "issuerUniqueID"
260	                    } else {
261	                        "subjectUniqueID"
262	                    };
263	                    if version < 1 {
264	                        return Err(format!(
265	                            "{what} is only allowed in v2 or v3 certificates, this is v1"
266	                        ));
267	                    }
268	                    if extensions_present {
269	                        return Err(format!(
270	                            "{what} must appear before the extensions field, \
271	                             which is the last field of tbsCertificate"
272	                        ));
273	                    }
274	                    if field.tag == 0x81 {
275	                        if issuer_uid_seen {
276	                            return Err("duplicate issuerUniqueID field".to_string());
277	                        }
278	                        if subject_uid_seen {
279	                            return Err(
280	                                "issuerUniqueID must appear before subjectUniqueID".to_string()
281	                            );
282	                        }
283	                        issuer_uid_seen = true;
284	                    } else if subject_uid_seen {
285	                        return Err("duplicate subjectUniqueID field".to_string());
286	                    } else {
287	                        subject_uid_seen = true;
288	                    }
289	                    check_bit_string(field.content, what)?;
290	                }
291	                0xA1 | 0xA2 => {
292	                    let what = if field.tag == 0xA1 {
293	                        "issuerUniqueID"
294	                    } else {
295	                        "subjectUniqueID"
296	                    };
297	                    return Err(format!(
298	                        "{what} must be an implicitly tagged primitive BIT STRING \
299	                         (tag 0x{:02X}); constructed tag 0x{:02X} is an explicit wrapper \
300	                         and is not allowed",
301	                        field.tag - 0x20,
302	                        field.tag
303	                    ));
304	                }
305	                0xA3 => {
306	                    if extensions_present {
307	                        return Err("duplicate extensions field".to_string());
308	                    }
309	                    if version != 2 {
310	                        let name = if version == 0 {
311	                            "v1"
312	                        } else {
313	                            "v2"
314	                        };
315	                        return Err(format!(
316	                            "extensions are only allowed in v3 certificates, this is {name}"
317	                        ));
318	                    }
319	                    check_extensions(field.content)?;
320	                    extensions_present = true;
321	                }
322	                other => {
323	                    return Err(format!(
324	                        "unexpected field after subjectPublicKeyInfo (tag 0x{other:02X}): \
325	                         only issuerUniqueID [1], subjectUniqueID [2] and extensions [3] \
326	                         are allowed there, and extensions must be last"
327	                    ));
328	                }
329	            }
330	            t = rest;
331	        }
332	
333	        let serial_hex = format_serial(serial.content)?;
334	        let issuer = format_name(issuer, "issuer")?;
335	        let subject = format_name(subject, "subject")?;
336	
337	        let v = validity.content;
338	        let (nb, v2) = read_tlv(v)?;
339	        let (na, v3) = read_tlv(v2)?;
340	        if !v3.is_empty() {
341	            return Err("trailing data in validity".to_string());
342	        }
343	        let not_before = format_time(nb)?;
344	        let not_after = format_time(na)?;
345	
346	        Ok(Cert {
347	            subject,
348	            issuer,
349	            serial_hex,
350	            not_before,
351	            not_after,
352	        })
353	    }
354	
355	    /// Validate the content of the extensions field, i.e. the bytes wrapped
356	    /// by `[3] EXPLICIT`:
357	    ///
358	    /// ```text
359	    /// Extensions ::= SEQUENCE SIZE (1..MAX) OF Extension
360	    /// Extension  ::= SEQUENCE {
361	    ///   extnID    OBJECT IDENTIFIER,
362	    ///   critical  BOOLEAN DEFAULT FALSE,
363	    ///   extnValue OCTET STRING }
364	    /// ```
365	    ///
366	    /// The wrapper must contain exactly one non-empty Extensions SEQUENCE.
367	    /// Every extension must contain its OID and OCTET STRING in that order,
368	    /// with at most one (DER-encoded) BOOLEAN between them and nothing after.
369	    /// Extension contents are never interpreted: unknown but well-formed
370	    /// extension OIDs are accepted and `critical: TRUE` is not a failure.
371	    ///
372	    /// Each extension type (its complete OID) may occur at most once in the
373	    /// list. Identity is the OID alone — critical flag, value content and
374	    /// value length never distinguish two entries — so a duplicate is neither
375	    /// picked between, merged nor dropped: the whole certificate is rejected,
376	    /// whether the duplicates are adjacent or separated by other extensions.
377	    fn check_extensions(wrapper: &[u8]) -> Result<(), String> {
378	        let (list, rest) = read_tagged(wrapper, TAG_SEQUENCE, "extensions")?;
379	        if !rest.is_empty() {
380	            return Err("extensions wrapper contains data after the Extensions SEQUENCE".to_string());
381	        }
382	        if list.content.is_empty() {
383	            return Err("extensions SEQUENCE is empty".to_string());
384	        }
385	
386	        // Complete OIDs (parsed arcs) already seen in this list. DER mandates
387	        // one shortest encoding per OID and `parse_oid` enforces it, so equal
388	        // arcs mean the same OID regardless of raw bytes; the list is short,
389	        // a linear scan keeps the representation simple.
390	        let mut seen_oids: Vec<Vec<u64>> = Vec::new();
391	        let mut buf = list.content;
392	        while !buf.is_empty() {
393	            let (ext, rest) = read_tagged(buf, TAG_SEQUENCE, "extension")?;
394	            buf = rest;
395	
396	            let (oid, after_oid) = read_tagged(ext.content, TAG_OID, "extension OID")?;
397	            let oid_arcs =
398	                parse_oid(oid.content).map_err(|e| format!("extension OID: {e}"))?;
399	            if seen_oids.contains(&oid_arcs) {
400	                return Err(format!(
401	                    "duplicate extension type OID {}: an extension OID may appear at most once \
402	                     in the extensions list, regardless of its critical flag or extension value \
403	                     (duplicate entries are not selected between, merged or removed)",
404	                    arcs_to_string(&oid_arcs)
405	                ));
406	            }
407	            seen_oids.push(oid_arcs);
408	
409	            // critical is optional; whatever stands between the OID and the
410	            // OCTET STRING must be exactly one BOOLEAN if it is present.
411	            let (maybe_bool, after_critical) = read_tlv(after_oid)
412	                .map_err(|e| format!("extension after OID: {e}"))?;
413	            let (octets, after_octets) = if maybe_bool.tag == TAG_BOOLEAN {
414	                match maybe_bool.content {
415	                    [0xFF] => {}
416	                    [0x00] => {
417	                        return Err(
418	                            "extension critical: explicit DER encoding of DEFAULT FALSE is not allowed"
419	                                .to_string()
420	                        )
421	                    }
422	                    _ => {
423	                        return Err(
424	                            "extension critical: invalid DER encoding of BOOLEAN".to_string()
425	                        )
426	                    }
427	                }
428	                read_tagged(after_critical, TAG_OCTET_STRING, "extension value")?
429	            } else {
430	                // Not a BOOLEAN: this element must itself be the extnValue.
431	                if maybe_bool.tag != TAG_OCTET_STRING {
432	                    return Err(format!(
433	                        "extension must contain a critical BOOLEAN then an OCTET STRING, \
434	                         got tag 0x{:02X}",
435	                        maybe_bool.tag
436	                    ));
437	                }
438	                (maybe_bool, after_critical)
439	            };
440	            // An empty OCTET STRING is legal; its bytes are not interpreted.
441	            let _ = octets.content;
442	            if !after_octets.is_empty() {
443	                return Err("trailing data in extension".to_string());
444	            }
445	        }
446	        Ok(())
447	    }
448	
449	    /// SubjectPublicKeyInfo ::= SEQUENCE {
450	    ///   algorithm        AlgorithmIdentifier,
451	    ///   subjectPublicKey BIT STRING }
452	    /// Nothing may be missing and no extra elements may follow.
453	    fn check_spki(spki: Tlv) -> Result<(), String> {
454	        let (alg, rest) = read_tagged(
455	            spki.content,
456	            TAG_SEQUENCE,
457	            "subjectPublicKeyInfo algorithm identifier",
458	        )?;
459	        check_algorithm_identifier(alg)?;
460	        let (key, rest) = read_tagged(rest, TAG_BIT_STRING, "subjectPublicKey")?;
461	        check_bit_string(key.content, "subjectPublicKey")?;
462	        if !rest.is_empty() {
463	            return Err("trailing data in subjectPublicKeyInfo".to_string());
464	        }
465	        Ok(())
466	    }
467	
468	    /// Why the content of an AlgorithmIdentifier SEQUENCE failed the shared
469	    /// structural check in `split_algorithm_identifier`. Each variant carries
470	    /// only the raw facts; every reader maps them onto its own established
471	    /// error wording (the public-key position names "algorithm OID" and
472	    /// "algorithm parameters", the signature algorithm positions name their
473	    /// own location).
474	    enum AlgIdError {
475	        /// The leading OID element could not be read as one complete TLV.
476	        OidRead(String),
477	        /// The first element is present but is not an OID.
478	        OidTag(u8),
479	        /// The OID element exists but its content is not a valid OID
480	        /// (empty, truncated or non-minimal base-128 arcs).
481	        OidContent(String),
482	        /// A parameter element follows the OID but cannot be read as one
483	        /// complete TLV.
484	        ParamsRead(String),
485	        /// Bytes remain after the parameter element: parameters are one
486	        /// OPTIONAL element, never several.
487	        ExtraAfterParams,
488	    }
489	
490	    /// Split the content of an AlgorithmIdentifier SEQUENCE into its
491	    /// algorithm OID and optional parameters, enforcing the structure every
492	    /// reader of an algorithm identifier shares:
493	    ///
494	    /// ```text
495	    /// AlgorithmIdentifier ::= SEQUENCE {
496	    ///   algorithm  OBJECT IDENTIFIER,
497	    ///   parameters ANY DEFINED BY algorithm OPTIONAL }
498	    /// ```
499	    ///
500	    /// The content must start with one complete, shortest-encoded OID,
501	    /// followed by either nothing or exactly one complete DER parameter
502	    /// value, and nothing after that. Absent parameters and an explicit NULL
503	    /// are both accepted and the parameter content is never interpreted for
504	    /// any particular algorithm; an unknown but well-formed OID is accepted.
505	    /// The parameter TLV is returned as its full original encoding (tag,
506	    /// length and content), sliced straight from the input, so callers that
507	    /// compare two identifiers can do so at the DER byte level.
508	    fn split_algorithm_identifier(
509	        content: &[u8],
510	    ) -> Result<(Tlv<'_>, Option<&[u8]>), AlgIdError> {
511	        let (oid, rest) = read_tlv(content).map_err(AlgIdError::OidRead)?;
512	        if oid.tag != TAG_OID {
513	            return Err(AlgIdError::OidTag(oid.tag));
514	        }
515	        parse_oid(oid.content).map_err(AlgIdError::OidContent)?;
516	        let params = if rest.is_empty() {
517	            None
518	        } else {
519	            let (_params, after) = read_tlv(rest).map_err(AlgIdError::ParamsRead)?;
520	            if !after.is_empty() {
521	                return Err(AlgIdError::ExtraAfterParams);
522	            }
523	            // Keep the full parameter TLV (tag, length and content), sliced
524	            // straight from the enclosing content; `read_tlv` already proved
525	            // it is a complete value.
526	            Some(&rest[..rest.len() - after.len()])
527	        };
528	        Ok((oid, params))
529	    }
530	
531	    /// Validate the AlgorithmIdentifier inside SubjectPublicKeyInfo: the
532	    /// shared structure from `split_algorithm_identifier`, reported with the
533	    /// public-key position's own wording.
534	    fn check_algorithm_identifier(alg: Tlv) -> Result<(), String> {
535	        split_algorithm_identifier(alg.content)
536	            .map(|_| ())
537	            .map_err(|e| match e {
538	                AlgIdError::OidRead(e) => format!("algorithm OID: {e}"),
539	                AlgIdError::OidTag(tag) => {
540	                    format!("expected algorithm OID (tag 0x06), got 0x{tag:02X}")
541	                }
542	                AlgIdError::OidContent(e) => format!("algorithm OID: {e}"),
543	                AlgIdError::ParamsRead(e) => format!("algorithm parameters: {e}"),
544	                AlgIdError::ExtraAfterParams => "multiple algorithm parameters".to_string(),
545	            })
546	    }
547	
548	    /// One of the certificate's two signature algorithm descriptions, kept as
549	    /// raw slices so two copies can be compared at the DER byte level: the OID
550	    /// content (arcs in their shortest encoding) and the complete parameter
551	    /// TLV (tag, length and content), or no parameter at all. An absent
552	    /// parameter and an explicit NULL are different representations.
553	    #[derive(Clone, Copy, PartialEq, Eq)]
554	    struct SignatureAlgorithm<'a> {
555	        oid_content: &'a [u8],
556	        params: Option<&'a [u8]>,
557	    }
558	
559	    /// Parse and fully validate one signatureAlgorithm SEQUENCE, applying the
560	    /// shared AlgorithmIdentifier structure from `split_algorithm_identifier`
561	    /// and keeping the raw pieces for the byte-level comparison of the two
562	    /// copies. `loc` names which of the two copies is being checked ("outer
563	    /// signatureAlgorithm" or the copy inside tbsCertificate) and prefixes
564	    /// every error message.
565	    fn parse_signature_algorithm<'a>(
566	        alg: Tlv<'a>,
567	        loc: &str,
568	    ) -> Result<SignatureAlgorithm<'a>, String> {
569	        let (oid, params) = split_algorithm_identifier(alg.content).map_err(|e| match e {
570	            AlgIdError::OidRead(e) => format!("{loc}: {e}"),
571	            AlgIdError::OidTag(tag) => format!(
572	                "{loc}: algorithm must start with an OID (tag 0x06), got tag 0x{tag:02X}"
573	            ),
574	            AlgIdError::OidContent(e) => format!("{loc}: {e}"),
575	            AlgIdError::ParamsRead(e) => format!("{loc}: algorithm parameters: {e}"),
576	            AlgIdError::ExtraAfterParams => {
577	                format!("{loc}: extra element after the algorithm parameters")
578	            }
579	        })?;
580	        Ok(SignatureAlgorithm {
581	            oid_content: oid.content,
582	            params,
583	        })
584	    }
