586	    /// Describe the disagreement between the outer signatureAlgorithm and the
587	    /// copy inside tbsCertificate. Both copies parse on their own; they merely
588	    /// fail to name the same algorithm or the same parameter representation.
589	    fn mismatch_message(outer: &SignatureAlgorithm<'_>, inner: &SignatureAlgorithm<'_>) -> String {
590	        const OUTER: &str = "the outer signatureAlgorithm";
591	        const INNER: &str = "the signatureAlgorithm in tbsCertificate";
592	        if outer.oid_content != inner.oid_content {
593	            let outer_oid = parse_oid(outer.oid_content)
594	                .map(|arcs| arcs_to_string(&arcs))
595	                .unwrap_or_else(|_| "?".to_string());
596	            let inner_oid = parse_oid(inner.oid_content)
597	                .map(|arcs| arcs_to_string(&arcs))
598	                .unwrap_or_else(|_| "?".to_string());
599	            return format!(
600	                "signature algorithm mismatch: {OUTER} names OID {outer_oid}, but {INNER} \
601	                 names OID {inner_oid}"
602	            );
603	        }
604	        match (outer.params, inner.params) {
605	            (Some(outer_params), Some(inner_params)) if outer_params != inner_params => {
606	                format!(
607	                    "signature algorithm mismatch: both copies name the same algorithm OID but \
608	                     their parameters have different DER encodings ({OUTER} has {}, {INNER} has {})",
609	                    hex_of(outer_params),
610	                    hex_of(inner_params),
611	                )
612	            }
613	            (Some(_), None) => format!(
614	                "signature algorithm mismatch: {OUTER} carries parameters but {INNER} omits them \
615	                 (an absent parameter and an explicit value are different representations)"
616	            ),
617	            (None, Some(_)) => format!(
618	                "signature algorithm mismatch: {INNER} carries parameters but {OUTER} omits them \
619	                 (an absent parameter and an explicit value are different representations)"
620	            ),
621	            // PartialEq already proved the copies unequal; reaching any other
622	            // arm here would be a logic error rather than a malformed cert.
623	            _ => "signature algorithm mismatch between the two signatureAlgorithm copies"
624	                .to_string(),
625	        }
626	    }
