628	    fn hex_of(bytes: &[u8]) -> String {
629	        let mut s = String::with_capacity(bytes.len() * 2);
630	        for b in bytes {
631	            write!(s, "{b:02X}").unwrap();
632	        }
633	        s
634	    }
