636	    /// Validate the DER content of a BIT STRING: one leading byte counting
637	    /// unused bits (0..=7), and when the count is nonzero those low bits of
638	    /// the final data byte must all be zero. An empty bit string is only
639	    /// legal with a zero count.
640	    fn check_bit_string(content: &[u8], what: &str) -> Result<(), String> {
641	        let unused = *content
642	            .first()
643	            .ok_or_else(|| format!("{what} BIT STRING is missing the unused-bits byte"))?;
644	        if unused > 7 {
645	            return Err(format!("{what} BIT STRING has invalid unused-bits count {unused}"));
646	        }
647	        let data = &content[1..];
648	        if data.is_empty() {
649	            if unused != 0 {
650	                return Err(format!(
651	                    "{what} BIT STRING declares {unused} unused bits but has no data"
652	                ));
653	            }
654	            return Ok(());
655	        }
656	        if unused != 0 && data[data.len() - 1] & ((1u8 << unused) - 1) != 0 {
657	            return Err(format!(
658	                "{what} BIT STRING has set bits among the {unused} unused trailing bits"
659	            ));
660	        }
661	        Ok(())
662	    }
