664	    /// Render the serial number as upper-case hex, matching the integer value
665	    /// (a DER sign-padding 0x00 byte is not part of the number).
666	    fn format_serial(content: &[u8]) -> Result<String, String> {
667	        if content.is_empty() {
668	            return Err("empty serial number".to_string());
669	        }
670	        if content.len() > 1 && content[0] == 0xFF && content[1] & 0x80 == 0 {
671	            return Err("non-minimal serial number encoding".to_string());
672	        }
673	        if content.len() > 1 && content[0] == 0x00 && content[1] & 0x80 == 0 {
674	            return Err("non-minimal serial number encoding".to_string());
675	        }
676	        if content[0] & 0x80 != 0 && !(content.len() > 1 && content[0] == 0x00) {
677	            return Err("negative serial number".to_string());
678	        }
679	        let digits = if content.len() > 1 && content[0] == 0x00 {
680	            &content[1..]
681	        } else {
682	            content
683	        };
684	        let mut s = String::with_capacity(digits.len() * 2);
685	        for b in digits {
686	            write!(s, "{b:02X}").unwrap();
687	        }
688	        if s.is_empty() {
689	            s.push_str("00");
690	        }
691	        Ok(s)
692	    }
