694	    /// Name ::= SEQUENCE OF RDN; rendered per RFC 4514 (RDNs reversed,
695	    /// multi-valued RDNs joined with '+'). Values of known attribute types
696	    /// are emitted as real UTF-8 text (non-ASCII content preserved verbatim)
697	    /// when their tag has a text decoder; a known type carrying any other
698	    /// readable DER value (e.g. postalAddress as a SEQUENCE) keeps its short
699	    /// name and uses the '#' form carrying the value's full DER encoding in
700	    /// hex. Attributes without a known short name use their dotted OID with
701	    /// the same '#' form.
702	    ///
703	    /// Each RDN is a DER SET OF, so its complete AttributeTypeAndValue
704	    /// encodings must be sorted by their full encoding bytes (tag, then
705	    /// length, then content — the encoding, never the display name, dotted
706	    /// OID text or decoded value). The check is per RDN; it never reorders
707	    /// the members itself. `what` names the name being checked ("subject" or
708	    /// "issuer") so an ordering failure identifies it in the error message.
709	    fn format_name(name: Tlv, what: &str) -> Result<String, String> {
710	        let mut rdn_buf = name.content;
711	        let mut rdns: Vec<String> = Vec::new();
712	        while !rdn_buf.is_empty() {
713	            let (set, rest) = read_tagged(rdn_buf, TAG_SET, "RelativeDistinguishedName")?;
714	            rdn_buf = rest;
715	
716	            let mut atv_buf = set.content;
717	            let mut parts = Vec::new();
718	            // Raw full encoding (tag, length and content) of each member of
719	            // this SET OF, straight from the certificate: DER SET OF ordering
720	            // compares the complete member encodings byte for byte. Equal
721	            // encodings may legitimately repeat and stay adjacent.
722	            let mut members: Vec<&[u8]> = Vec::new();
723	            while !atv_buf.is_empty() {
724	                let atv_start = atv_buf;
725	                let (atv, rest) =
726	                    read_tagged(atv_buf, TAG_SEQUENCE, "AttributeTypeAndValue")?;
727	                atv_buf = rest;
728	                members.push(&atv_start[..atv_start.len() - atv_buf.len()]);
729	
730	                let (oid, after_oid) = read_tagged(atv.content, TAG_OID, "attribute OID")?;
731	                let (value, after_value) = read_tlv(after_oid)?;
732	                if !after_value.is_empty() {
733	                    return Err("trailing data in attribute value".to_string());
734	                }
735	
736	                let oid_arcs = parse_oid(oid.content)?;
737	
738	                // The value's own type rules apply before any display decision:
739	                // a PrintableString must hold only the RFC 5280 PrintableString
740	                // alphabet, a BMPString must hold whole 16-bit BMP characters
741	                // and a UniversalString must hold whole 32-bit Unicode code
742	                // points, whether the attribute later renders as text for a
743	                // known short name or as '#'-hex for an unknown type. The hex
744	                // form must never let an illegal byte or code point through,
745	                // and illegal content cannot be dropped or replaced. An empty
746	                // value stays legal. `what` names the offending name
747	                // ("subject"/"issuer").
748	                if value.tag == TAG_PRINTABLE_STRING
749	                    && !is_printable_string(value.content)
750	                {
751	                    return Err(format!(
752	                        "{what} name: PrintableString attribute value contains an illegal \
753	                         character (only A-Z, a-z, 0-9, space and ' ( ) + , - . / : = ? are \
754	                         allowed)"
755	                    ));
756	                }
757	                if value.tag == TAG_BMP_STRING {
758	                    check_bmp_string(value.content, what)?;
759	                }
760	                if value.tag == TAG_UNIVERSAL_STRING {
761	                    check_universal_string(value.content, what)?;
762	                }
763	
764	                match oid_short_name(&oid_arcs) {
765	                    Some(label) => {
766	                        if is_text_value_tag(value.tag) {
767	                            // Supported string type: decode to escaped text.
768	                            // A decode failure (e.g. invalid UTF-8) means the
769	                            // certificate is corrupt; it must not be salvaged
770	                            // by falling back to the hex form.
771	                            let text = decode_attribute_value(value.tag, value.content)?;
772	                            parts.push(format!("{label}={}", escape_value(&text)));
773	                        } else {
774	                            // Known type but a legal value with no text decoder
775	                            // (SEQUENCE, OCTET STRING, ...): keep the short name
776	                            // and show the full original DER encoding as '#'-hex.
777	                            parts.push(format!("{label}=#{}", value_hex(after_oid, after_value)));
778	                        }
779	                    }
780	                    None => {
781	                        // Unknown attribute type: RFC 4514 requires the form
782	                        // OID=#hex, where the hex is the full DER encoding
783	                        // (tag, length and content) of the attribute value.
784	                        // Showing the value as hex does not bypass its type
785	                        // rules: UTF8String content must be valid UTF-8, a
786	                        // PrintableString must keep to its alphabet, a
787	                        // BMPString must hold legal BMP characters and a
788	                        // UniversalString must hold legal Unicode code points,
789	                        // checks already performed above before this match.
790	                        if value.tag == 0x0C {
791	                            std::str::from_utf8(value.content)
792	                                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?;
793	                        }
794	                        let hex = value_hex(after_oid, after_value);
795	                        parts.push(format!("{}=#{hex}", arcs_to_string(&oid_arcs)));
796	                    }
797	                }
798	            }
799	            if parts.is_empty() {
800	                return Err("empty RelativeDistinguishedName".to_string());
801	            }
802	            check_rdn_der_order(&members, what)?;
803	            rdns.push(parts.join("+"));
804	        }
805	        rdns.reverse();
806	        Ok(rdns.join(","))
807	    }
