809	    /// Validate one RDN as a DER SET OF: every member's complete
810	    /// AttributeTypeAndValue encoding must be less than or equal to the next
811	    /// one under ordinary byte ordering of tag, length and content. The
812	    /// comparison runs on the raw encodings only — CN/O short names, dotted
813	    /// OID text and decoded values never enter into it — and equal adjacent
814	    /// members (duplicate attributes) are allowed. The members are never
815	    /// reordered to make an unsorted input pass. `what` is "subject" or
816	    /// "issuer" and identifies the offending name in the error message.
817	    fn check_rdn_der_order(members: &[&[u8]], what: &str) -> Result<(), String> {
818	        for pair in members.windows(2) {
819	            if pair[0] > pair[1] {
820	                return Err(format!(
821	                    "{what} name: attributes of a multi-valued RelativeDistinguishedName \
822	                     are not encoded in DER SET OF order (the members must be sorted by \
823	                     their complete DER encoding bytes: tag, then length, then content)"
824	                ));
825	            }
826	        }
827	        Ok(())
828	    }
829	
830	    /// Uppercase hex of one complete value TLV, sliced straight from the
831	    /// input bytes (`around` ends at `rest`). The original tag and length
832	    /// bytes survive verbatim, including a legal long-form length; nothing is
833	    /// re-encoded and content alone is never emitted.
834	    fn value_hex(around: &[u8], rest: &[u8]) -> String {
835	        let tlv_len = around.len() - rest.len();
836	        let mut hex = String::with_capacity(tlv_len * 2);
837	        for b in &around[..tlv_len] {
838	            write!(hex, "{b:02X}").unwrap();
839	        }
840	        hex
841	    }
