843	    /// Tags whose attribute values have a direct text decoding in
844	    /// `decode_attribute_value`. Every other tag that `read_tlv` accepts is a
845	    /// legal non-text value for display purposes and is rendered as '#'-hex.
846	    fn is_text_value_tag(tag: u8) -> bool {
847	        matches!(
848	            tag,
849	            0x0C | 0x12 | 0x13 | 0x14 | 0x16 | 0x1A | 0x1B | 0x1C | 0x1E
850	        )
851	    }
852	
853	    fn parse_oid(content: &[u8]) -> Result<Vec<u64>, String> {
854	        if content.is_empty() {
855	            return Err("empty OID".to_string());
856	        }
857	        let mut arcs = Vec::new();
858	        // The first subidentifier encodes the first two arcs as
859	        // 40*first + second and is itself a base-128 quantity, so it can
860	        // span multiple content bytes (e.g. 2.999 encodes as 0x88 0x37).
861	        let mut i = 0;
862	        let first = read_oid_arc(content, &mut i)?;
863	        match first {
864	            0..=39 => {
865	                arcs.push(0);
866	                arcs.push(first);
867	            }
868	            40..=79 => {
869	                arcs.push(1);
870	                arcs.push(first - 40);
871	            }
872	            _ => {
873	                arcs.push(2);
874	                arcs.push(first - 80);
875	            }
876	        }
877	        while i < content.len() {
878	            arcs.push(read_oid_arc(content, &mut i)?);
879	        }
880	        Ok(arcs)
881	    }
882	
883	    /// Read one base-128 subidentifier starting at `*i`. Rejects trailing
884	    /// continuation bytes and non-minimal encodings.
885	    fn read_oid_arc(content: &[u8], i: &mut usize) -> Result<u64, String> {
886	        let start = *i;
887	        let mut value = 0u64;
888	        loop {
889	            let b = *content
890	                .get(*i)
891	                .ok_or_else(|| "truncated OID arc".to_string())?;
892	            value = value
893	                .checked_mul(128)
894	                .and_then(|v| v.checked_add((b & 0x7F) as u64))
895	                .ok_or_else(|| "OID arc overflow".to_string())?;
896	            *i += 1;
897	            if b & 0x80 == 0 {
898	                break;
899	            }
900	        }
901	        if *i - start > 1 && content[start] == 0x80 {
902	            return Err("non-minimal OID arc encoding".to_string());
903	        }
904	        Ok(value)
905	    }
906	
907	    fn arcs_to_string(arcs: &[u64]) -> String {
908	        arcs.iter()
909	            .map(u64::to_string)
910	            .collect::<Vec<_>>()
911	            .join(".")
912	    }
