914	    fn oid_short_name(arcs: &[u64]) -> Option<&'static str> {
915	        // X.520 / X.521 (2.5.4.*) and the commonly used LDAP/PKCS names.
916	        let name = match arcs {
917	            [2, 5, 4, 3] => "CN",
918	            [2, 5, 4, 4] => "SN",
919	            [2, 5, 4, 5] => "serialNumber",
920	            [2, 5, 4, 6] => "C",
921	            [2, 5, 4, 7] => "L",
922	            [2, 5, 4, 8] => "ST",
923	            [2, 5, 4, 9] => "STREET",
924	            [2, 5, 4, 10] => "O",
925	            [2, 5, 4, 11] => "OU",
926	            [2, 5, 4, 12] => "title",
927	            [2, 5, 4, 17] => "postalAddress",
928	            [2, 5, 4, 18] => "postalCode",
929	            [2, 5, 4, 20] => "telephoneNumber",
930	            [2, 5, 4, 42] => "givenName",
931	            [2, 5, 4, 43] => "initials",
932	            [2, 5, 4, 44] => "generationQualifier",
933	            [2, 5, 4, 46] => "dnQualifier",
934	            [2, 5, 4, 65] => "pseudonym",
935	            [0, 9, 2342, 19200300, 100, 1, 1] => "UID",
936	            [0, 9, 2342, 19200300, 100, 1, 25] => "DC",
937	            [1, 2, 840, 113549, 1, 9, 1] => "emailAddress",
938	            _ => return None,
939	        };
940	        Some(name)
