943	    /// Whether every byte belongs to the RFC 5280 PrintableString alphabet:
944	    /// A-Z, a-z, 0-9, space, and ' ( ) + , - . / : = ?. Every other byte
945	    /// (including @, _, tabs, newlines, NUL and 0x80..=0xFF) is illegal.
946	    /// An empty value passes, preserving the existing acceptance of empty
947	    /// contents.
948	    fn is_printable_string(content: &[u8]) -> bool {
949	        content.iter().all(|&b| matches!(
950	            b,
951	            b'A'..=b'Z'
952	                | b'a'..=b'z'
953	                | b'0'..=b'9'
954	                | b' '
955	                | b'\''
956	                | b'('
957	                | b')'
958	                | b'+'
959	                | b','
960	                | b'-'
961	                | b'.'
962	                | b'/'
963	                | b':'
964	                | b'='
965	                | b'?'
966	        ))
967	    }
968	
969	    /// Validate BMPString content: an even number of bytes read as big-endian
970	    /// 16-bit characters, each of which must be a Basic Multilingual Plane
971	    /// code point (U+0000..=U+FFFF) and never a UTF-16 surrogate
972	    /// (U+D800..=U+DFFF). Surrogates are not characters, so a lone high or
973	    /// low surrogate is corrupt, and so is an adjacent pair that UTF-16
974	    /// rules would combine into an astral-plane character — the pair must
975	    /// not be merged and displayed. An illegal value fails the whole
976	    /// certificate; bytes are never dropped or replaced to salvage it.
977	    /// Empty content stays legal, preserving the existing acceptance of
978	    /// empty values. `what` names the name being checked ("subject" or
979	    /// "issuer") so the error identifies the offending name.
980	    fn check_bmp_string(content: &[u8], what: &str) -> Result<(), String> {
981	        if content.len() % 2 != 0 {
982	            return Err(format!(
983	                "{what} name: BMPString attribute value has an odd length of {} byte(s) \
984	                 (the content must be a sequence of 16-bit characters)",
985	                content.len()
986	            ));
987	        }
988	        for pair in content.chunks_exact(2) {
989	            let unit = u16::from_be_bytes([pair[0], pair[1]]);
990	            if (0xD800..=0xDFFF).contains(&unit) {
991	                return Err(format!(
992	                    "{what} name: BMPString attribute value contains the surrogate code \
993	                     point U+{unit:04X}, which is not a legal character (U+D800..=U+DFFF \
994	                     are not characters and cannot appear, alone or in pairs)"
995	                ));
996	            }
997	        }
998	        Ok(())
999	    }
1000	
1001	    /// Validate UniversalString content: the bytes must form whole big-endian
1002	    /// 32-bit Unicode code points, so the length must be a multiple of four,
1003	    /// and every code point must lie in U+0000..=U+10FFFF and never be a
1004	    /// UTF-16 surrogate (U+D800..=U+DFFF). A trailing incomplete unit, a lone
1005	    /// surrogate (or a pair that UTF-16 rules would combine), or a value
1006	    /// above the Unicode ceiling is corrupt; the whole certificate fails and
1007	    /// no unit is dropped, replaced or merely hex-displayed to salvage it.
1008	    /// Empty content stays legal, preserving the existing acceptance of empty
1009	    /// values. `what` names the name being checked ("subject" or "issuer")
1010	    /// so the error identifies the offending name.
1011	    fn check_universal_string(content: &[u8], what: &str) -> Result<(), String> {
1012	        if content.len() % 4 != 0 {
1013	            return Err(format!(
1014	                "{what} name: UniversalString attribute value has a length of {} byte(s), \
1015	                 which is not a multiple of four (the content must be a sequence of \
1016	                 big-endian 32-bit Unicode code points)",
1017	                content.len()
1018	            ));
1019	        }
1020	        for unit in content.chunks_exact(4) {
1021	            let cp = u32::from_be_bytes([unit[0], unit[1], unit[2], unit[3]]);
1022	            if (0xD800..=0xDFFF).contains(&cp) {
1023	                return Err(format!(
1024	                    "{what} name: UniversalString attribute value contains the surrogate code \
1025	                     point U+{cp:04X}, which is not a legal character (U+D800..=U+DFFF are \
1026	                     not characters and cannot appear, alone or in pairs)"
1027	                ));
1028	            }
1029	            if cp > 0x10FFFF {
1030	                return Err(format!(
1031	                    "{what} name: UniversalString attribute value contains the code point \
1032	                     U+{cp:04X}, which is above the Unicode maximum U+10FFFF"
1033	                ));
1034	            }
1035	        }
1036	        Ok(())
1037	    }
