1039	    /// Decode a DirectoryString-style attribute value into UTF-8 text.
1040	    fn decode_attribute_value(tag: u8, content: &[u8]) -> Result<String, String> {
1041	        let s = match tag {
1042	            0x0C => std::str::from_utf8(content)
1043	                .map_err(|_| "invalid UTF-8 in UTF8String".to_string())?
1044	                .to_string(),
1045	            // ASCII-family strings: every byte is also its Unicode code point.
1046	            0x12 | 0x13 | 0x16 | 0x1A => content.iter().map(|&b| b as char).collect(),
1047	            // T.61 / GeneralString are conventionally treated as Latin-1 here.
1048	            0x14 | 0x1B => content.iter().map(|&b| b as char).collect(),
1049	            0x1E => {
1050	                if content.len() % 2 != 0 {
1051	                    return Err("odd-length BMPString".to_string());
1052	                }
1053	                // A BMPString character is one big-endian 16-bit BMP code
1054	                // point, never a UTF-16 surrogate: surrogate pairs must not
1055	                // be merged into astral-plane characters.
1056	                let mut s = String::with_capacity(content.len() / 2);
1057	                for c in content.chunks_exact(2) {
1058	                    let unit = u16::from_be_bytes([c[0], c[1]]);
1059	                    let ch = char::from_u32(unit as u32)
1060	                        .ok_or_else(|| "surrogate code point in BMPString".to_string())?;
1061	                    s.push(ch);
1062	                }
1063	                s
1064	            }
1065	            0x1C => {
1066	                if content.len() % 4 != 0 {
1067	                    return Err("invalid UniversalString length".to_string());
1068	                }
1069	                let mut s = String::new();
1070	                for c in content.chunks_exact(4) {
1071	                    let cp = u32::from_be_bytes([c[0], c[1], c[2], c[3]]);
1072	                    if (0xD800..=0xDFFF).contains(&cp) || cp > 0x10FFFF {
1073	                        return Err("invalid code point in UniversalString".to_string());
1074	                    }
1075	                    s.push(char::from_u32(cp).unwrap());
1076	                }
1077	                s
1078	            }
1079	            _ => {
1080	                return Err(format!(
1081	                    "unsupported attribute value string type (tag 0x{tag:02X})"
1082	                ))
1083	            }
1084	        };
1085	        Ok(s)
1086	    }
1087	
1088	    /// RFC 4514 value escaping; everything above the ASCII control range
1089	    /// (including CJK text) passes through unchanged.
1090	    fn escape_value(value: &str) -> String {
1091	        let mut out = String::with_capacity(value.len());
1092	        let last = value.chars().count().saturating_sub(1);
1093	        for (i, c) in value.chars().enumerate() {
1094	            let at_edge = i == 0 || i == last;
1095	            let needs_backslash = matches!(c, ',' | '+' | '"' | '\\' | '<' | '>' | ';')
1096	                || (at_edge && (c == ' ' || c == '#'));
1097	            if needs_backslash {
1098	                out.push('\\');
1099	                out.push(c);
1100	            } else if ('\0'..='\x1F').contains(&c) || c == '\x7F' {
1101	                let mut buf = [0u8; 4];
1102	                let b = c.encode_utf8(&mut buf).as_bytes()[0];
1103	                write!(out, "\\{b:02X}").unwrap();
1104	            } else {
1105	                out.push(c);
1106	            }
1107	        }
1108	        out
1109	    }
