1111	    fn format_time(tlv: Tlv) -> Result<String, String> {
1112	        let (y, mo, d, h, mi, se) = match tlv.tag {
1113	            TAG_UTC_TIME => {
1114	                let c = tlv.content;
1115	                if c.len() != 13 || c[12] != b'Z' {
1116	                    return Err("UTCTime must be YYMMDDHHMMSSZ".to_string());
1117	                }
1118	                let digits = &c[..12];
1119	                if !digits.iter().all(|b| b.is_ascii_digit()) {
1120	                    return Err("non-numeric UTCTime".to_string());
1121	                }
1122	                let n = |a: usize, b: usize| -> u32 {
1123	                    digits[a..=b].iter().fold(0, |acc, x| acc * 10 + (x - b'0') as u32)
1124	                };
1125	                let yy = n(0, 1);
1126	                let year = if yy < 50 { 2000 + yy } else { 1900 + yy };
1127	                (year as i32, n(2, 3), n(4, 5), n(6, 7), n(8, 9), n(10, 11))
1128	            }
