1	//! End-to-end regression tests for the name (Subject/Issuer) decoding and
2	//! display behavior documented in README.md.
3	//!
4	//! These tests drive the real `chainview` binary so the public contract is
5	//! locked as a whole: the five output lines and their order on success, and
6	//! exit code 2 with empty stdout plus the `chainview: invalid DER
7	//! certificate:` stderr prefix on malformed input. Only name decoding is
8	//! exercised — signature verification, trust and expiry are intentionally out
9	//! of scope.
10	//!
11	//! Certificates are built with the tiny zero-dependency DER constructor at the
12	//! bottom of this file, which lets individual name components (including
13	//! truncated or non-minimal value encodings) be crafted byte for byte.
14	
15	use std::fs;
16	use std::path::PathBuf;
17	use std::process::{Command, Output};
18	use std::sync::atomic::{AtomicU64, Ordering};
19	
20	const FIXED_SERIAL: &str = "0E8A4C2F9B17D603";
21	const FIXED_NOT_BEFORE: &str = "2026-01-15T09:30:00Z";
22	const FIXED_NOT_AFTER: &str = "2027-01-15T09:30:00Z";
23	
24	// ----- Known X.520 attribute OID arcs -------------------------------------
25	
26	const CN: &[u64] = &[2, 5, 4, 3];
27	const O: &[u64] = &[2, 5, 4, 10];
28	const C: &[u64] = &[2, 5, 4, 6];
29	const POSTAL_ADDRESS: &[u64] = &[2, 5, 4, 17];
30	const POSTAL_CODE: &[u64] = &[2, 5, 4, 18];
31	
32	// The spec example: a SEQUENCE containing only UTF8String "abc", with its
33	// complete DER encoding.
34	const POSTAL_ADDRESS_ABC_HEX: &str = "30050C03616263";
35	
36	// ----- Success cases -------------------------------------------------------
37	
38	#[test]
39	fn unknown_oid_uses_dotted_oid_and_full_der_hex() {
40	    // The exact README example: UTF8String "abc" for type 1.2.3.4 must render
41	    // as 1.2.3.4=#0C03616263 — tag, length and content, readable text or not.
42	    let subject = name(&[rdn(&[atv_utf8(&[1, 2, 3, 4], "abc")])]);
43	    let issuer = simple_cn_name("Test CA");
44	    let (out, _cert) = run_inspect("unknown-basic", &build_cert(&subject, &issuer));
45	
46	    assert_success(
47	        &out,
48	        "1.2.3.4=#0C03616263",
49	        "CN=Test CA",
50	    );
51	}
52	
53	#[test]
54	fn unknown_oid_value_preserves_long_form_length() {
55	    // A 128-byte content needs the long-form length 0x81 0x80; the hex must
56	    // carry the original TLV header verbatim instead of collapsing the length
57	    // or emitting only the content bytes.
58	    let long_text = "a".repeat(128);
59	    let subject = name(&[rdn(&[atv_utf8(&[1, 2, 3, 4], &long_text)])]);
60	    let issuer = simple_cn_name("Test CA");
61	    let (out, _cert) = run_inspect("unknown-longlen", &build_cert(&subject, &issuer));
62	
63	    let mut expected_hex = String::from("0C8180");
64	    expected_hex.push_str(&"61".repeat(128));
65	    assert_success(&out, &format!("1.2.3.4=#{expected_hex}"), "CN=Test CA");
66	}
