260	#[test]
261	fn empty_subject_keeps_empty_field_while_issuer_shows() {
262	    // An empty SEQUENCE is a valid empty name: the Subject line stays empty
263	    // (just "Subject: ") while Issuer renders normally. All five fields keep
264	    // their documented order, and the time fields are UTC regardless of the
265	    // machine zone.
266	    let subject = tlv(0x30, &[]); // Name ::= SEQUENCE {}
