275	            "Subject: \n\
276	             Issuer: CN=Example CA\n\
277	             Serial Number: {FIXED_SERIAL}\n\
278	             Not Before: {FIXED_NOT_BEFORE}\n\
279	             Not After: {FIXED_NOT_AFTER}\n"
