309	// ----- PrintableString (tag 0x13) character rules --------------------------
310	
311	#[test]
312	fn printable_string_with_legal_characters_displays_as_text() {
313	    // Every character of the RFC 5280 PrintableString alphabet is accepted:
314	    // letters, digits, space and ' ( ) + , - . / : = ?. The RFC 4514 text
315	    // escaping is unchanged: '+' and ',' are escaped anywhere, and leading and
316	    // trailing spaces keep their backslashes; the other punctuation passes
317	    // through verbatim.
318	    let subject = name(&[rdn(&[atv_printable(
319	        CN,
320	        b" John+Doe, Jr.'s (Section-1/2: A=B?) ",
321	    )])]);
322	    let issuer = simple_cn_name("Test CA");
323	    let (out, _cert) = run_inspect("printable-legal", &build_cert(&subject, &issuer));
324	
325	    assert_success(
326	        &out,
327	        "CN=\\ John\\+Doe\\, Jr.'s (Section-1/2: A=B?)\\ ",
328	        "CN=Test CA",
329	    );
