334	    // A legal PrintableString at an unknown OID is still shown by encoding
335	    // (never decoded to text): tag 0x13, length and content in uppercase hex.
336	    let subject = name(&[rdn(&[atv_printable(&[1, 2, 3, 4], b"abc")])]);
