354	#[test]
355	fn illegal_bytes_in_subject_printable_string_are_rejected() {
356	    // One illegal byte anywhere in a known attribute's PrintableString fails
357	    // the whole certificate; the byte must never be printed, replaced or
358	    // stripped. @, _, tab, LF, NUL and the whole 0x80..=0xFF range are all
359	    // outside the alphabet even though many are otherwise printable bytes.
360	    for bad in [
361	        b'@', b'_', b'%', b'&', b'*', b'!', b'"', b';', b'<', b'>', b'\\', b'#', b'[',
362	        b']', b'{', b'}', b'|', b'^', b'~', b'`', b'$', b'\t', b'\n', b'\r', 0x00, 0x01,
363	        0x1F, 0x7F, 0x80, 0xA9, 0xC3, 0xFF,
364	    ] {
