366	        let subject = name(&[rdn(&[atv_printable(CN, &value)])]);
367	        let issuer = simple_cn_name("Test CA");
368	        let (out, _cert) = run_inspect("printable-bad-subject", &build_cert(&subject, &issuer));
369	
370	        assert_invalid_certificate(&out);
371	        let stderr = lossy(&out.stderr);
372	        assert!(
373	            stderr.contains("subject") && stderr.contains("PrintableString"),
374	            "byte 0x{bad:02X} must fail as a subject PrintableString error: {stderr}"
375	        );
