432	#[test]
433	fn bmp_string_for_unknown_oid_still_uses_full_der_hex() {
434	    // A legal BMPString at an unknown OID is shown by encoding (never decoded
435	    // to text): tag 0x1E, length and content in uppercase hex.
436	    let subject = name(&[rdn(&[atv_bmp(&[1, 2, 3, 4], &bmp_units(&[0x0061, 0x0062]))])]);
437	    let issuer = simple_cn_name("Test CA");
