920	    // value text "aaa" would come well before "z". A comparison based on
921	    // decoded values would reject this legal certificate.
922	    let subject = name(&[rdn(&[
923	        atv_utf8(CN, "z"),
924	        atv_utf8(&[1, 2, 3, 4], "aaa"),
925	    ])]);
926	    let issuer = simple_cn_name("Test CA");
927	    let (out, _cert) = run_inspect("order-by-length", &build_cert(&subject, &issuer));
928	
929	    assert_success(&out, "CN=z+1.2.3.4=#0C03616161", "CN=Test CA");
930	
931	    // The reverse encoding is corrupt: the longer outer encoding must not
932	    // come first, regardless of the '#' text representation.
933	    let subject = name(&[rdn(&[
934	        atv_utf8(&[1, 2, 3, 4], "aaa"),
935	        atv_utf8(CN, "z"),
936	    ])]);
937	    let (out, _cert) = run_inspect("order-by-length-bad", &build_cert(&subject, &issuer));
938	    assert_invalid_certificate(&out);
939	}
940	
941	#[test]
942	fn each_rdn_is_checked_independently() {
943	    // Two RDNs in one name: the first (outermost) group is fine, a later
944	    // group carries O-before-CN out of order (OID arc 0x0A > 0x03). The
945	    // whole name must be rejected rather than treated as one set or checked
946	    // only on a group of the checker's choosing.
947	    let subject = name(&[
948	        rdn(&[atv_utf8(C, "CN")]),
949	        rdn(&[atv_utf8(O, "y"), atv_utf8(CN, "x")]),
950	    ]);
951	    let issuer = simple_cn_name("Test CA");
952	    let (out, _cert) = run_inspect("bad-order-second-rdn", &build_cert(&subject, &issuer));
953	
954	    assert_invalid_certificate(&out);
955	    assert!(lossy(&out.stderr).contains("subject"));
956	}
957	
958	#[test]
959	fn identical_adjacent_members_are_allowed_and_not_deduplicated() {
960	    // Two members with byte-for-byte identical complete encodings compare
961	    // equal and therefore satisfy the sorted SET OF rule; both must still
962	    // appear in the output (no merging, no false ordering failure).
963	    let subject = name(&[rdn(&[
964	        atv_utf8(CN, "dup"),
965	        atv_utf8(CN, "dup"),
966	    ])]);
967	    let issuer = simple_cn_name("Test CA");
968	    let (out, _cert) = run_inspect("dup-members", &build_cert(&subject, &issuer));
969	
970	    assert_success(&out, "CN=dup+CN=dup", "CN=Test CA");
971	}
972	
973	#[test]
974	fn single_attribute_rdn_always_satisfies_set_ordering() {
975	    // A SET OF with one member is trivially sorted, whatever the attribute
976	    // and value encodings are.
977	    let subject = name(&[
978	        rdn(&[atv_utf8(C, "CN")]),
979	        rdn(&[atv_utf8(O, "org")]),
980	        rdn(&[atv_utf8(CN, "host")]),
981	    ]);
982	    let issuer = simple_cn_name("Test CA");
983	    let (out, _cert) = run_inspect("single-member-rdns", &build_cert(&subject, &issuer));
984	
985	    assert_success(&out, "CN=host,O=org,C=CN", "CN=Test CA");
986	}
987	
988	// ----- CLI contract: usage, version and unreadable files ------------------
989	
990	#[test]
991	fn version_flag_keeps_its_output() {
992	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
993	        .arg("--version")
994	        .output()
995	        .expect("running chainview");
996	    assert_eq!(out.status.code(), Some(0));
997	    assert!(out.stderr.is_empty());
998	    assert_eq!(lossy(&out.stdout), "chainview 0.1.0\n");
999	}
1000	
1001	#[test]
1002	fn missing_path_is_a_usage_error() {
1003	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
1004	        .arg("inspect")
1005	        .output()
1006	        .expect("running chainview");
1007	    assert_eq!(out.status.code(), Some(2));
1008	    assert!(out.stdout.is_empty());
1009	    assert_eq!(
1010	        lossy(&out.stderr),
1011	        "Usage: chainview inspect <DER-FILE>\n       chainview --version\n"
1012	    );
1013	}
1014	
1015	#[test]
1016	fn unreadable_file_keeps_its_error_contract() {
1017	    let missing = std::env::temp_dir().join("chainview-name-test-definitely-missing.der");
1018	    let _ = fs::remove_file(&missing);
1019	    let out = Command::new(env!("CARGO_BIN_EXE_chainview"))
1020	        .arg("inspect")
1021	        .arg(&missing)
1022	        .output()
1023	        .expect("running chainview");
1024	    assert_eq!(out.status.code(), Some(2));
1025	    assert!(out.stdout.is_empty());
1026	    let stderr = lossy(&out.stderr);
1027	    assert!(
1028	        stderr.starts_with(&format!(
1029	            "chainview: cannot read certificate file '{}': ",
1030	            missing.display()
1031	        )),
1032	        "unexpected stderr: {stderr}"
1033	    );
1034	}
1035	
1036	// ----- Assertions / process plumbing --------------------------------------
1037	
1038	fn assert_success(out: &Output, subject: &str, issuer: &str) {
1039	    assert_eq!(out.status.code(), Some(0), "stderr={}", lossy(&out.stderr));
1040	    assert!(out.stderr.is_empty(), "stderr={}", lossy(&out.stderr));
1041	    assert_eq!(
1042	        lossy(&out.stdout),
1043	        format!(
1044	            "Subject: {subject}\n\
1045	             Issuer: {issuer}\n\
1046	             Serial Number: {FIXED_SERIAL}\n\
1047	             Not Before: {FIXED_NOT_BEFORE}\n\
1048	             Not After: {FIXED_NOT_AFTER}\n"
1049	        )
1050	    );
1051	}
1052	
1053	/// Every malformed-input case shares the documented contract: exit code 2,
1054	/// nothing on stdout (so no name field can be printed before the error is
1055	/// noticed), and the fixed invalid-certificate message prefix on stderr.
1056	fn assert_invalid_certificate(out: &Output) {
1057	    assert_eq!(
1058	        out.status.code(),
1059	        Some(2),
1060	        "stdout={} stderr={}",
1061	        lossy(&out.stdout),
1062	        lossy(&out.stderr)
1063	    );
1064	    assert!(
1065	        out.stdout.is_empty(),
1066	        "stdout must be empty on failure, got: {}",
1067	        lossy(&out.stdout)
1068	    );
1069	    let stderr = lossy(&out.stderr);
1070	    assert!(
1071	        stderr.starts_with("chainview: invalid DER certificate: "),
1072	        "unexpected stderr: {stderr}"
1073	    );
1074	    // A non-empty reason after the fixed prefix.
1075	    assert!(
1076	        stderr["chainview: invalid DER certificate: ".len()..].trim().len() > 1,
1077	        "missing error reason in stderr: {stderr}"
1078	    );
1079	}
1080	
1081	fn lossy(bytes: &[u8]) -> String {
1082	    String::from_utf8_lossy(bytes).into_owned()
1083	}
1084	
1085	fn run_inspect(tag: &str, data: &[u8]) -> (Output, TempCert) {
1086	    let cert = TempCert::new(tag, data);
1087	    let output = Command::new(env!("CARGO_BIN_EXE_chainview"))
1088	        .arg("inspect")
1089	        .arg(&cert.path)
1090	        .output()
1091	        .expect("running chainview");
1092	    (output, cert)
1093	}
1094	
1095	struct TempCert {
1096	    path: PathBuf,
1097	}
1098	
1099	impl TempCert {
1100	    fn new(tag: &str, data: &[u8]) -> Self {
1101	        static COUNTER: AtomicU64 = AtomicU64::new(0);
1102	        let unique = COUNTER.fetch_add(1, Ordering::Relaxed);
1103	        let path = std::env::temp_dir().join(format!(
1104	            "chainview-name-test-{}-{tag}-{unique}.der",
1105	            std::process::id()
1106	        ));
1107	        fs::write(&path, data).expect("writing temp certificate");
1108	        TempCert { path }
1109	    }
1110	}
1111	
1112	impl Drop for TempCert {
1113	    fn drop(&mut self) {
1114	        let _ = fs::remove_file(&self.path);
1115	    }
1116	}
1117	
1118	// ----- Certificate / DER construction -------------------------------------
1119	//
1120	// Only the structural pieces needed here. Lengths are always emitted in the
1121	// minimal DER form, except where a test injects raw bytes to exercise
1122	// rejection of non-minimal or truncated encodings.
1123	
1124	fn simple_cn_name(cn: &str) -> Vec<u8> {
1125	    name(&[rdn(&[atv_utf8(CN, cn)])])
1126	}
1127	
1128	/// Assemble a complete, parseable v1 DER certificate with fixed serial,
1129	/// validity and key material around the supplied Subject/Issuer names.
1130	fn build_cert(subject: &[u8], issuer: &[u8]) -> Vec<u8> {
1131	    let serial = tlv(0x02, &[0x0E, 0x8A, 0x4C, 0x2F, 0x9B, 0x17, 0xD6, 0x03]);
1132	    let validity = seq(&concat(&[
1133	        &tlv(0x17, b"260115093000Z"), // UTCTime 2026-01-15T09:30:00Z
1134	        &tlv(0x17, b"270115093000Z"), // UTCTime 2027-01-15T09:30:00Z
1135	    ]));
1136	    let spki = seq(&concat(&[
1137	        &seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 1]), &tlv(0x05, &[])])),
1138	        &tlv(0x03, &[0x00, 0x01, 0x00]), // BIT STRING, zero unused bits
1139	    ]));
1140	
1141	    let tbs = seq(&concat(&[
1142	        &serial,
1143	        &signature_algorithm(),
1144	        issuer,
1145	        &validity,
1146	        subject,
1147	        &spki,
1148	    ]));
1149	    seq(&concat(&[&tbs, &signature_algorithm(), &tlv(0x03, &[0x00])]))
1150	}
1151	
1152	fn signature_algorithm() -> Vec<u8> {
1153	    // sha256WithRSAEncryption with explicit NULL parameters.
1154	    seq(&concat(&[&oid(&[1, 2, 840, 113549, 1, 1, 11]), &tlv(0x05, &[])]))
1155	}
1156	
1157	fn name(rdns: &[Vec<u8>]) -> Vec<u8> {
1158	    tlv(
1159	        0x30,
1160	        &concat(&rdns.iter().map(Vec::as_slice).collect::<Vec<_>>()),
1161	    )
1162	}
1163	
1164	fn rdn(atvs: &[Vec<u8>]) -> Vec<u8> {
1165	    tlv(
1166	        0x31,
1167	        &concat(&atvs.iter().map(Vec::as_slice).collect::<Vec<_>>()),
1168	    )
1169	}
1170	
1171	/// AttributeTypeAndValue ::= SEQUENCE { type OID, value ANY } — `value` is the
1172	/// complete DER TLV of the value.
1173	fn atv(arcs: &[u64], value: &[u8]) -> Vec<u8> {
1174	    seq(&concat(&[&oid(arcs), value]))
1175	}
1176	
1177	fn atv_utf8(arcs: &[u64], text: &str) -> Vec<u8> {
1178	    atv(arcs, &tlv(0x0C, text.as_bytes()))
1179	}
1180	
1181	fn atv_printable(arcs: &[u64], bytes: &[u8]) -> Vec<u8> {
1182	    atv(arcs, &tlv(0x13, bytes))
1183	}
1184	
1185	fn atv_bmp(arcs: &[u64], content: &[u8]) -> Vec<u8> {
1186	    atv(arcs, &tlv(0x1E, content))
1187	}
1188	
1189	fn atv_universal(arcs: &[u64], content: &[u8]) -> Vec<u8> {
1190	    atv(arcs, &tlv(0x1C, content))
1191	}
1192	
1193	/// Big-endian 16-bit units, the wire form of a BMPString's characters.
1194	fn bmp_units(units: &[u16]) -> Vec<u8> {
1195	    units.iter().flat_map(|u| u.to_be_bytes()).collect()
1196	}
1197	
1198	/// Big-endian 32-bit code points, the wire form of a UniversalString's units.
1199	fn universal_units(units: &[u32]) -> Vec<u8> {
1200	    units.iter().flat_map(|u| u.to_be_bytes()).collect()
1201	}
1202	
1203	fn oid(arcs: &[u64]) -> Vec<u8> {
1204	    assert!(arcs.len() >= 2);
1205	    let mut content = oid_arc(arcs[0] * 40 + arcs[1]);
1206	    for &arc in &arcs[2..] {
1207	        content.extend_from_slice(&oid_arc(arc));
1208	    }
1209	    tlv(0x06, &content)
1210	}
1211	
1212	fn oid_arc(mut value: u64) -> Vec<u8> {
1213	    let mut out = vec![(value % 128) as u8];
1214	    value /= 128;
1215	    while value > 0 {
1216	        out.push(0x80 | (value % 128) as u8);
1217	        value /= 128;
1218	    }
1219	    out.reverse();
1220	    out
1221	}
1222	
1223	fn seq(content: &[u8]) -> Vec<u8> {
1224	    tlv(0x30, content)
1225	}
1226	
1227	fn tlv(tag: u8, content: &[u8]) -> Vec<u8> {
1228	    let mut out = vec![tag];
1229	    out.extend_from_slice(&der_len(content.len()));
1230	    out.extend_from_slice(content);
1231	    out
1232	}
1233	
1234	fn der_len(n: usize) -> Vec<u8> {
1235	    if n < 0x80 {
1236	        vec![n as u8]
1237	    } else {
1238	        let mut body = Vec::new();
1239	        let mut v = n;
1240	        while v > 0 {
1241	            body.push((v & 0xFF) as u8);
1242	            v >>= 8;
1243	        }
1244	        body.reverse();
1245	        let mut out = vec![0x80 | body.len() as u8];
1246	        out.extend_from_slice(&body);
1247	        out
1248	    }
1249	}
1250	
1251	fn concat(parts: &[&[u8]]) -> Vec<u8> {
1252	    let mut out = Vec::new();
1253	    for part in parts {
1254	        out.extend_from_slice(part);
1255	    }
1256	    out
1257	}
1258	
1259	fn hex(bytes: &[u8]) -> String {
1260	    let mut s = String::with_capacity(bytes.len() * 2);
1261	    for b in bytes {
1262	        use std::fmt::Write;
1263	        write!(s, "{b:02X}").unwrap();
1264	    }
1265	    s
1266	}
