    let mut inner = oid(POSTAL_ADDRESS);
    inner.extend_from_slice(&[0x30, 0x05, 0x0C, 0x02, 0xAB]); // len 5, 4 present
    let subject = name(&[rdn(&[seq(&inner)])]);
    let issuer = simple_cn_name("Test CA");
