import subprocess, os, tempfile

def tlv(t, v):
    n=len(v)
    if n<0x80: L=bytes([n])
    else:
        b=n.to_bytes((n.bit_length()+7)//8,'big'); L=bytes([0x80|len(b)])+b
    return bytes([t])+L+v
def oid(arcs):
    body=bytes([arcs[0]*40+arcs[1]])+b''.join(arc(a) for a in arcs[2:])
    return tlv(6,body)
def arc(v):
    out=[v&0x7f]; v>>=7
    while v: out.append(0x80|(v&0x7f)); v>>=7
    return bytes(reversed(out))
def seq(*xs): return tlv(0x30,b''.join(xs))
def atv(arcs,val): return seq(oid(arcs),val)
def name(rdns): return tlv(0x30,b''.join(rdns))
def rdn(atvs): return tlv(0x31,b''.join(atvs))

serial=tlv(2,bytes.fromhex("0E8A4C2F9B17D603"))
alg=seq(oid([1,2,840,113549,1,1,11]),tlv(5,b""))
val=tlv(0x17,b"260115093000Z"); na=tlv(0x17,b"270115093000Z")
validity=seq(val,na)
spki=seq(seq(oid([1,2,840,113549,1,1,1]),tlv(5,b"")),tlv(3,b"\x00\x01\x00"))
issuer=name([rdn([atv([2,5,4,3],tlv(0x0c,b"Test CA"))])])

def cert(subj):
    tbs=seq(serial,alg,issuer,validity,subj,spki)
    return seq(tbs,alg,tlv(3,b"\x00"))

# Subject: unknown OID 1.2.3.4 with UniversalString U+1F600 -> #1C040001F600
s1=name([rdn([atv([1,2,3,4],tlv(0x1C,bytes.fromhex("0001F600")))])])
# Subject: CN with UniversalString U+1F600 -> literal char; plus empty unknown & empty CN
s2=name([
  rdn([atv([1,2,3,4],tlv(0x1C,b""))]),           # empty unknown universal -> #1C00
  rdn([atv([2,5,4,3],tlv(0x13,b""))]),           # empty printable CN -> CN=
  rdn([atv([2,5,4,3],tlv(0x1C,bytes.fromhex("0001F600")))]),
])
# Illegal: unknown OID PrintableString containing '@' -> must reject, exit 2, empty stdout
sbad=name([rdn([atv([1,2,3,4],tlv(0x13,b"a@b"))])])
# Illegal: unknown OID UniversalString surrogate pair -> reject
ssurr=name([rdn([atv([1,2,3,4],tlv(0x1C,bytes.fromhex("0000D83D0000DE00")))])])

binpath="./target/debug/chainview"
def run(tag,c):
    p=os.path.join(tempfile.gettempdir(),f"cv_{tag}.der")
    open(p,"wb").write(c)
    r=subprocess.run([binpath,"inspect",p],capture_output=True)
    os.remove(p)
    return r.returncode,r.stdout.decode("utf8","replace"),r.stderr.decode("utf8","replace")

for tag,s in [("ok1",s1),("ok2",s2)]:
    rc,out,err=run(tag,cert(s))
    print(f"--- {tag} rc={rc} stderr={err!r}")
    print(out)
for tag,s in [("bad_print",sbad),("bad_surr",ssurr)]:
    rc,out,err=run(tag,cert(s))
    print(f"--- {tag} rc={rc} stdout_empty={out==''}")
    print("   stderr:",err.strip())
